import React, { useState } from 'react';
// import { useNavigate } from 'react-router-dom';
import { login, register } from '../services/api';

const Login = () => {
  const [isRegister, setIsRegister] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    try {
      if (isRegister) {
        await register(username, password);
        setIsRegister(false); // Switch to login after register
        alert("Registration successful! Please login.");
      } else {
        const data = await login(username, password);
        localStorage.setItem('token', data.access_token);
        // Force a page reload to ensure Layout picks up the token state correctly
        window.location.href = '/dashboard';
      }
    } catch (err) {
      setError('Authentication failed. Check credentials or server status.');
    }
  };

  return (
    <div className="flex items-center justify-center h-screen bg-scifi-bg text-neon-green font-mono">
      <div className="w-96 p-8 border border-neon-green/30 rounded bg-scifi-panel shadow-[0_0_30px_rgba(0,255,157,0.1)] relative overflow-hidden">
        
        {/* Decorative elements */}
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-neon-green to-transparent opacity-50"></div>

        <h1 className="text-3xl font-bold mb-8 text-center tracking-[0.2em] text-white">QS-VAULT</h1>
        
        <form onSubmit={handleSubmit} className="flex flex-col gap-5">
          <div className="flex flex-col gap-1">
             <label className="text-[10px] uppercase text-gray-500">Identity</label>
             <input
                type="text"
                className="p-3 bg-black border border-gray-700 focus:outline-none focus:border-neon-green text-white rounded transition-colors"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
          </div>
          
          <div className="flex flex-col gap-1">
             <label className="text-[10px] uppercase text-gray-500">Passcode</label>
             <input
                type="password"
                className="p-3 bg-black border border-gray-700 focus:outline-none focus:border-neon-green text-white rounded transition-colors"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
          </div>

          {error && <p className="text-red-500 text-xs border border-red-500/20 bg-red-900/10 p-2 rounded">{error}</p>}
          
          <button type="submit" className="mt-2 p-3 bg-neon-green hover:bg-green-400 text-black font-bold uppercase tracking-wider rounded shadow-[0_0_10px_rgba(0,255,157,0.4)] transition-all">
            {isRegister ? 'Initialize Identity' : 'Access Gateway'}
          </button>
        </form>
        
        <p 
          className="mt-6 text-xs text-center cursor-pointer text-gray-500 hover:text-white transition-colors"
          onClick={() => setIsRegister(!isRegister)}
        >
          {isRegister ? "Existing User? Login" : "New User? Register Identity"}
        </p>
      </div>
    </div>
  );
};

export default Login;
